insert into recipes(id,data,sort,hidden) values('r035','{"id":"r035","cat":"生殖系统","title_zh":"分娩准备","title_en":"Birth Preparation","usage_zh":"进入待产室后涂抹小腹，少量多次。","usage_en":"Only after entering the labour/delivery room, apply a small amount to the lower abdomen, several times as needed.","items":[{"oil":"快乐鼠尾草","oil_en":"Clary Sage","product":"clary-sage-oil","drops":10}],"alt_items":null,"choose":null,"carrier":"","carrier_ml":null,"tags":["女性养护","下腹"],"flags":["pregnancy_avoid"],"source":"library","review":true}'::jsonb,34,true) on conflict(id) do nothing;
insert into recipes(id,data,sort,hidden) values('r084','{"id":"r084","cat":"消化系统","title_zh":"肠胃舒适胶囊","title_en":"Tummy Comfort Capsule","usage_zh":"将推荐精油按数量及顺序加入植物空胶囊中内服。","usage_en":"Add the recommended oils, in the listed amounts and order, to an empty vegetable capsule and take by mouth.","items":[{"oil":"椒样薄荷","oil_en":"Peppermint","product":"peppermint-essential-oil","drops":1},{"oil":"芫荽籽","oil_en":"Coriander","product":"coriander-oil","drops":5},{"oil":"小茴香","oil_en":"Fennel","product":"sweet-fennel-oil","drops":4}],"alt_items":null,"choose":null,"carrier":"","carrier_ml":null,"tags":["消化"],"flags":["internal"],"source":"library","review":true}'::jsonb,83,true) on conflict(id) do nothing;
insert into recipes(id,data,sort,hidden) values('r092','{"id":"r092","cat":"消化系统","title_zh":"腹部日常养护","title_en":"Daily Belly Care","usage_zh":"涂抹小腹，早中晚各1次。需要时，也可各取3滴装入胶囊内服。","usage_en":"Apply to the lower abdomen. Morning, midday and evening. When needed, 3 drops of each oil may also be placed in a capsule and taken by mouth.","items":[{"oil":"椒样薄荷","oil_en":"Peppermint","product":"peppermint-essential-oil","drops":10},{"oil":"芫荽籽","oil_en":"Coriander","product":"coriander-oil","drops":10},{"oil":"小茴香","oil_en":"Fennel","product":"sweet-fennel-oil","drops":10}],"alt_items":null,"choose":null,"carrier":"","carrier_ml":null,"tags":["消化"],"flags":["internal"],"source":"library","review":true}'::jsonb,91,true) on conflict(id) do nothing;
insert into recipes(id,data,sort,hidden) values('r096','{"id":"r096","cat":"消化系统","title_zh":"婴幼儿温和抚触","title_en":"Gentle Baby Massage","usage_zh":"任选一种精油加入基础油中混合均匀，涂抹足底（肝反射区），早中晚各1次。","usage_en":"Choose one oil and blend well into a carrier oil, then apply to the soles of the feet (liver reflex zone). Morning, midday and evening.","items":[{"oil":"天竺葵","oil_en":"Geranium","product":"geranium-oil","drops":null},{"oil":"迷迭香","oil_en":"Rosemary","product":"rosemary-oil","drops":null},{"oil":"柠檬","oil_en":"Lemon","product":"lemon-oil","drops":null}],"alt_items":null,"choose":{"pick":1,"drops":30},"carrier":"","carrier_ml":null,"tags":["儿童","足部"],"flags":["infant"],"source":"library","review":true}'::jsonb,95,true) on conflict(id) do nothing;
