insert into recipes(id,data,sort,hidden) values('r129','{"id":"r129","cat":"皮肤","title_zh":"出门肌肤护理","title_en":"Before-You-Go Skin Care","usage_zh":"出门前15分钟涂抹需要护理的肌肤（注意避开眼睛），可随身携带。","usage_en":"Apply to skin 15 minutes before heading out, keeping away from the eyes; carry with you.","items":[{"oil":"椒样薄荷","oil_en":"Peppermint","product":"peppermint-essential-oil","drops":1},{"oil":"丁香花蕾","oil_en":"Clove","product":"clove-bud-oil","drops":6},{"oil":"乳香","oil_en":"Frankincense","product":"frankincense-essential-oil","drops":2}],"alt_items":null,"choose":null,"carrier":"","carrier_ml":null,"tags":["肌肤","户外"],"flags":["eye_area","hot_oil"],"source":"library","review":true}'::jsonb,128,true) on conflict(id) do nothing;
