insert into recipes(id,data,sort,hidden) values('r186','{"id":"r186","cat":"五官","title_zh":"耳部清爽护理","title_en":"Fresh Ear Care","usage_zh":"蘸取少量涂抹外耳道口，少量多次。","usage_en":"Dab a small amount at the entrance of the outer ear canal, several times a day.","items":[{"oil":"罗勒","oil_en":"Basil","product":"basil-oil","drops":10},{"oil":"茶树","oil_en":"Tea Tree (Melaleuca)","product":"tea-tree-oil-nhp","drops":10},{"oil":"乳香","oil_en":"Frankincense","product":"frankincense-essential-oil","drops":5}],"alt_items":null,"choose":null,"carrier":"","carrier_ml":null,"tags":["耳周"],"flags":[],"source":"library","review":true}'::jsonb,185,true) on conflict(id) do nothing;
