insert into recipes(id,data,sort,hidden) values('g06','{"id":"g06","cat":"日常养护","title_zh":"三伏天养生胶囊","title_en":"Summer Wellness Capsule","usage_zh":"在滴管瓶中混合后，每次取2-3滴装入胶囊内服，每天早晚各1次。","usage_en":"Blend in a dropper bottle, then place 2–3 drops in a capsule and take by mouth, morning and evening.","items":[{"oil":"新瑞活力","oil_en":"MetaPWR","product":null,"drops":100},{"oil":"芫荽叶","oil_en":"Cilantro","product":"cilantro-oil","drops":50},{"oil":"广藿香","oil_en":"Patchouli","product":"patchouli-oil-nhp","drops":50},{"oil":"元气","oil_en":"RevitaZen","product":"revitazen","drops":50}],"alt_items":null,"choose":null,"carrier":"滴管瓶混合","carrier_ml":null,"tags":["消化","季节"],"flags":["internal"],"source":"grace","review":true}'::jsonb,195,true) on conflict(id) do nothing;
insert into recipes(id,data,sort,hidden) values('g09','{"id":"g09","cat":"五官","title_zh":"耳部舒适养护","title_en":"Ear Comfort Care","usage_zh":"每次取5-6滴滴在棉球上，睡前将棉球轻放于耳道口，第二天取出。","usage_en":"Place 5–6 drops on a cotton ball and rest it gently at the entrance of the ear before bed; remove the next morning.","items":[{"oil":"永久花","oil_en":"Helichrysum","product":"helichrysum-oil-nhp","drops":null},{"oil":"罗勒","oil_en":"Basil","product":"basil-oil","drops":null},{"oil":"天竺葵","oil_en":"Geranium","product":"geranium-oil","drops":null},{"oil":"薰衣草","oil_en":"Lavender","product":"lavender-oil","drops":null},{"oil":"薄荷","oil_en":"Peppermint","product":"peppermint-essential-oil","drops":null}],"alt_items":null,"choose":null,"carrier":"","carrier_ml":null,"tags":["耳周","睡眠"],"flags":[],"source":"grace","review":true}'::jsonb,198,true) on conflict(id) do nothing;